import{_ as o,C as r,o as a,c as n,ag as s,E as d}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Glossary","description":"Common terms used across the Takoform documentation and specification","frontmatter":{"page_title":"Takoform glossary","description":"Common terms used across the Takoform documentation and specification"},"headers":[],"relativePath":"docs/glossary.md","filePath":"docs/glossary.md"}'),i={name:"docs/glossary.md"};function c(m,e,l,h,p,g){const t=r("StatusNote");return a(),n("div",null,[e[0]||(e[0]=s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Common terms used across the Takoform documentation. Definitions here are summaries; the normative meaning always lives in the <a href="/spec/">specification</a> documents.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Form</strong></td><td>One portable desired-state contract: a named, versioned definition of what a workload needs from any host.</td></tr><tr><td><strong>FormRef</strong></td><td>The exact immutable identity of a Form: versionless reverse-DNS family group, <code>kind</code>, definition version, and schema digest. Compatibility is never inferred from a name alone.</td></tr><tr><td><strong>Form Definition</strong></td><td>The deterministic, data-only JSON document describing one Form: desired/observed/output schemas, immutable fields, lifecycle capabilities, and interface descriptors (<a href="/spec/form-definition/">form definition</a>).</td></tr><tr><td><strong>Form Package</strong></td><td>A closed, data-only distribution of one Form Definition plus its fixtures, bound by a canonical content digest (<a href="/spec/form-package/">form package</a>). No executable or credential content is allowed.</td></tr><tr><td><strong>schemaDigest</strong></td><td>SHA-256 over the RFC 8785 canonical Form Definition bytes.</td></tr><tr><td><strong>packageDigest</strong></td><td>SHA-256 over the RFC 8785 canonical package index; it is the publication locator (<code>sha256-&lt;hex&gt;</code>) of a package.</td></tr><tr><td><strong>Epoch</strong></td><td>The API-group boundary of the specification. The pre-Beta epochs (<code>forms.takoform.com/v1alpha1</code> and <code>/v1alpha2</code>) were withdrawn (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); current design work uses namespaced Form Family groups instead of a new bare epoch.</td></tr><tr><td><strong>Form Family</strong></td><td>A versionless namespaced Form group (<a href="/spec/form-families.html">Form Families</a>) such as <code>edge.forms.takoform.com</code>: related Forms sharing exact Interface and Binding contracts. The current candidate has eight families and 31 Experimental <code>0.x</code> FormRefs; Edge contains 16. Family membership and Specification 1.0 grant no Form maturity.</td></tr><tr><td><strong>Resource Role</strong></td><td>The closed role enum — <code>identity</code>, <code>revision</code>, <code>deployment</code>, <code>attachment</code>, <code>policy</code> — deciding one Form&#39;s lifecycle mechanics: revisions are immutable, deployments move traffic, attachments activate inward events.</td></tr><tr><td><strong>Envelope</strong></td><td>The package API version used to carry a Form. Current versionless-group candidates use <code>packages.forms.takoform.com/v1alpha5</code>; retained Provider 2.1.1/v1beta1 packages keep <code>v1alpha4</code>, and earlier envelope identities remain immutable history.</td></tr><tr><td><strong>Space</strong></td><td>An opaque, case-sensitive scope identity (<code>SpaceID</code>) that scopes Resources, Interface reads, idempotency, and provider configuration.</td></tr><tr><td><strong>Host</strong></td><td>Any implementation of the Host API that advertises exact FormRefs, executes the portable lifecycle, and owns placement, credentials, and recovery.</td></tr><tr><td><strong>Host API</strong></td><td>The versioned HTTP contract (<a href="/spec/host-api/">host API</a>): discovery, exact Form availability, preview/apply, read/import/observe/delete, fencing, and stable errors. The current Specification wire is <code>forms.takoform.com/v1</code>; v1beta4 is a retained pre-v1 design snapshot and v1beta1 remains the immutable Provider 2.1.1 lane.</td></tr><tr><td><strong>Discovery</strong></td><td>The versioned well-known endpoint at which a host advertises its API, Forms, and features: <code>/.well-known/takoform/v1</code> for the current Host API.</td></tr><tr><td><strong>Lane</strong></td><td>One exact Host protocol path. Specification 1.0 defines <code>forms.takoform.com/v1</code> independently of Provider publication or Form maturity. Provider <code>3.0.0</code> is the Registry-published non-normative reference implementation for the current 31 Forms; Provider <code>2.1.1</code> remains on retained v1beta1 history. Neither can block the Specification.</td></tr><tr><td><strong>Substrate</strong></td><td>The concrete backend or cloud an implementation runs on. Substrate operation is never portable Form state.</td></tr><tr><td><strong>Interface declaration</strong></td><td>The withdrawn v1alpha2 lane&#39;s read-only <code>(name, version)</code> descriptor surface; superseded by exact digest-bound <a href="/spec/interface-contract/">Interface contracts</a>.</td></tr><tr><td><strong>Interface contract</strong></td><td>One exact named capability contract a Form&#39;s service exposes, such as <code>edge.kv@1.0.0</code> (<a href="/spec/interface-contract/">interface contracts</a>). A service with different semantics is a different contract, never a variant.</td></tr><tr><td><strong>Binding contract</strong></td><td>The typed contract behind one outward capability binding a revision holds, such as <code>module-worker.edge-kv@1.0.0</code> (<a href="/spec/binding-contract/">binding contracts</a>). Inward activation (routes, domains, cron, consumption) is an attachment, never a binding.</td></tr><tr><td><strong>Standard service</strong></td><td>A sealed Host-resolved runtime slot identified by opaque <code>standards.takoform.com/v1</code> plus a reverse-DNS protocol string. Takoform has no central protocol enum and the slot grants no portable lifecycle over a service Resource.</td></tr><tr><td><strong>artifact manifest</strong></td><td>The content-addressed manifest (<code>artifacts.takoform.com/v1alpha1</code>) that commits a bundle&#39;s modules by exact size and sha256 digest through the <a href="/spec/artifact-transport/">artifact transport</a> upload API.</td></tr><tr><td><strong>uid / generation / revision</strong></td><td>The Host API v1 resource identity triple: <code>uid</code> is the host-issued immutable resource identity; <code>generation</code> increments only when the portable desired spec changes and fences updates; <code>revision</code> increments on any representation change and fences deletes.</td></tr><tr><td><strong>Proposal</strong></td><td>Mutable, unversioned design material for a Form that has not earned a public FormRef.</td></tr><tr><td><strong>Experimental</strong></td><td>A reproducible public Form on a <code>0.x</code> line whose semantics may still change under the documented compatibility policy.</td></tr><tr><td><strong>Stable</strong></td><td>An evidence-earned Form contract with independent implementations, interoperability, and operational experience.</td></tr><tr><td><strong>Legacy</strong></td><td>The lifecycle state after the current line is no longer recommended for new work. The historical Legacy epoch itself was withdrawn (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); its bytes stay in repository history.</td></tr><tr><td><strong>Admission</strong></td><td>The withdrawn historical central-evidence process. There is no current central approval or admission.</td></tr><tr><td><strong>resource_version</strong></td><td>The withdrawn v2 lane&#39;s canonical positive-decimal desired-state version; on Host API v1 the <code>ETag</code> is the quoted <code>revision</code> and the generation stays the mutation fence.</td></tr><tr><td><strong>Idempotency-Key</strong></td><td>A deterministic client-supplied key scoping mutation replay; a retry must reuse the same key and request bytes.</td></tr><tr><td><strong>Checkpoint</strong></td><td>A cumulative, hash-chained revocation checkpoint carrying every statement from sequence 1 through the current sequence.</td></tr><tr><td><strong>Drift</strong></td><td>A lifecycle outcome derived from validated observed evidence; it is not a separate host operation.</td></tr></tbody></table>',3)),d(t)])}const v=o(i,[["render",c]]);export{u as __pageData,v as default};
